import sys

def main():
    s = sys.stdin.read().rstrip('\n')
    tokens = []
    current = []
    for c in s:
        if c.isalpha():
            current.append(c)
        elif c in ',.!?':
            if current:
                tokens.append(('word', ''.join(current)))
                current = []
            tokens.append(('punct', c))
        else:
            if current:
                tokens.append(('word', ''.join(current)
                current = []
    if current:
        tokens.append(('word', ''.join(current)))

    result = []
    for i, (ttype, val) in enumerate(tokens):
        if ttype == 'word':
            if result:
                result.append(val)
            else:
                result.append(val)
        else:
            result.append(val)

    out_parts = []
    for i, (ttype, val) in enumerate(result):
        if i > 0:
            prev_ttype, prev_val = result[i-1]
            if prev_ttype == 'word' and ttype == 'word':
                out_parts.append(' ')
            elif prev_ttype == 'punct':
                out_parts.append(' ')
        out_parts.append(val)

    print(''.join(out_parts), end='')

if __name__ == "__main__":
    main()
